// AgentServiceServer is the server API for AgentService service.
// All implementations must embed UnimplementedAgentServiceServer
// for forward compatibility.
type AgentServiceServer interface {
	// Ping reports that the agent is up, and its version.
	Ping(context.Context, *PingRequest) (*PingResponse, error)
	// ServiceStatus reports the state of a managed service.
	ServiceStatus(context.Context, *ServiceStatusRequest) (*ServiceStatusResponse, error)
	// ServiceAction starts, stops, restarts or reloads a managed service.
	ServiceAction(context.Context, *ServiceActionRequest) (*ServiceActionResponse, error)
	// FileWriteManaged writes a generated config file inside an allow-listed
	// directory, atomically. If a validator is given and fails, the previous
	// file is restored and the call fails with FAILED_PRECONDITION.
	FileWriteManaged(context.Context, *FileWriteManagedRequest) (*FileWriteManagedResponse, error)
	// FileRemoveManaged removes a generated config file (same rules as write).
	FileRemoveManaged(context.Context, *FileRemoveManagedRequest) (*FileRemoveManagedResponse, error)
	// AccountEnsure creates or updates the Linux side of a hosting account:
	// user and group, home folder layout, resource limits (systemd slice) and
	// disk quota where the filesystem supports it. Idempotent.
	AccountEnsure(context.Context, *AccountEnsureRequest) (*AccountEnsureResponse, error)
	// AccountSetSuspended locks or unlocks an account's Linux user.
	AccountSetSuspended(context.Context, *AccountSetSuspendedRequest) (*AccountSetSuspendedResponse, error)
	// AccountDelete stops the user's processes and removes the Linux user, its
	// home folder and its slice. It refuses users that XCP did not create.
	AccountDelete(context.Context, *AccountDeleteRequest) (*AccountDeleteResponse, error)
	// SiteApply writes an account's Apache virtual host and PHP-FPM pool. The
	// agent renders them from these typed fields (callers never send config
	// text, ADR-0004), runs apachectl -t and php-fpm -t, rolls back on failure
	// and reloads gracefully. NOT_FOUND: Apache or PHP-FPM is not installed.
	SiteApply(context.Context, *SiteApplyRequest) (*SiteApplyResponse, error)
	// SiteRemove deletes an account's virtual host and PHP-FPM pools.
	SiteRemove(context.Context, *SiteRemoveRequest) (*SiteRemoveResponse, error)
	// PHPVersions lists the installed PHP-FPM versions, oldest first.
	PHPVersions(context.Context, *PHPVersionsRequest) (*PHPVersionsResponse, error)
	// DNSZoneApply makes PowerDNS serve exactly this zone: its records, NS
	// records from the name servers and an SOA kept by the agent. Only the
	// RRsets that differ change, in one transaction. NOT_FOUND: PowerDNS is
	// not installed.
	DNSZoneApply(context.Context, *DNSZoneApplyRequest) (*DNSZoneApplyResponse, error)
	// DNSZoneDelete removes a zone from PowerDNS.
	DNSZoneDelete(context.Context, *DNSZoneDeleteRequest) (*DNSZoneDeleteResponse, error)
	// HostCertificateInstall installs the certificate of the server's host
	// name (/etc/xcp/ssl/hostname.crt and .key) for the panel, and later mail
	// and FTP. It must cover the host name and be valid now; xcp-api picks it
	// up without a restart.
	HostCertificateInstall(context.Context, *HostCertificateInstallRequest) (*HostCertificateInstallResponse, error)
	// MySQLStatus reports MariaDB's version and the installed phpMyAdmin.
	MySQLStatus(context.Context, *MySQLStatusRequest) (*MySQLStatusResponse, error)
	// MySQLAccountApply makes the account's users, password hashes, grants
	// and lock state exactly as given, and creates missing databases. It
	// never drops a database.
	MySQLAccountApply(context.Context, *MySQLAccountApplyRequest) (*MySQLAccountApplyResponse, error)
	// MySQLAccountRemove drops all databases and users of an account.
	MySQLAccountRemove(context.Context, *MySQLAccountRemoveRequest) (*MySQLAccountRemoveResponse, error)
	// MySQLDatabaseSizes lists the account's databases with their sizes.
	MySQLDatabaseSizes(context.Context, *MySQLDatabaseSizesRequest) (*MySQLDatabaseSizesResponse, error)
	// MySQLDatabaseDrop drops one database with its data.
	MySQLDatabaseDrop(context.Context, *MySQLDatabaseDropRequest) (*MySQLDatabaseDropResponse, error)
	// MySQLDatabaseRename moves all tables to a new database and drops the
	// old one. INVALID_ARGUMENT if it has views, triggers, routines or events.
	MySQLDatabaseRename(context.Context, *MySQLDatabaseRenameRequest) (*MySQLDatabaseRenameResponse, error)
	// MySQLSignon creates a temporary user for phpMyAdmin with all privileges
	// on the given databases and a one-time ticket to sign in with it.
	MySQLSignon(context.Context, *MySQLSignonRequest) (*MySQLSignonResponse, error)
	// MySQLSignonExpire drops expired sign-on users and unused tickets.
	MySQLSignonExpire(context.Context, *MySQLSignonExpireRequest) (*MySQLSignonExpireResponse, error)
	// MySQLRootPassword lets root in with a password too (next to the socket).
	MySQLRootPassword(context.Context, *MySQLRootPasswordRequest) (*MySQLRootPasswordResponse, error)
	// MailAccountApply stores an account's mail (domains, mailboxes,
	// forwarders, default addresses, DKIM keys) and rebuilds the global
	// maps. INVALID_ARGUMENT if another account has mail for one of its domains.
	MailAccountApply(context.Context, *MailAccountApplyRequest) (*MailAccountApplyResponse, error)
	// MailAccountRemove drops an account's mail from the maps.
	MailAccountRemove(context.Context, *MailAccountRemoveRequest) (*MailAccountRemoveResponse, error)
	// MailSettingsApply renders the mail servers' configuration.
	MailSettingsApply(context.Context, *MailSettingsApplyRequest) (*MailSettingsApplyResponse, error)
	// MailWebmailSignon makes a temporary IMAP password (8 hours) for a
	// mailbox of the account that may log in, and a one-time ticket for
	// Roundcube (ADR-0008). NOT_FOUND: webmail is not installed.
	MailWebmailSignon(context.Context, *MailWebmailSignonRequest) (*MailWebmailSignonResponse, error)
	// MailWebmailExpire drops expired temporary passwords and tickets.
	MailWebmailExpire(context.Context, *MailWebmailExpireRequest) (*MailWebmailExpireResponse, error)
	// UserHelperStart starts an account's file helper socket (ADR-0009):
	// xcp-userd then runs as the account's user on the first connection.
	// FAILED_PRECONDITION: not an XCP account.
	UserHelperStart(context.Context, *UserHelperStartRequest) (*UserHelperStartResponse, error)
	// FTPAccountApply stores all FTP logins of an account for xcp-ftpauth,
	// after making their folders as the account's user. INVALID_ARGUMENT if
	// another account has one of the logins.
	FTPAccountApply(context.Context, *FTPAccountApplyRequest) (*FTPAccountApplyResponse, error)
	// FTPAccountRemove drops an account's FTP logins.
	FTPAccountRemove(context.Context, *FTPAccountRemoveRequest) (*FTPAccountRemoveResponse, error)
	// CronAccountApply stores all cron jobs of an account; the agent starts
	// the due ones every minute as transient units in the account's slice.
	CronAccountApply(context.Context, *CronAccountApplyRequest) (*CronAccountApplyResponse, error)
	// CronAccountRemove drops an account's cron jobs and their last runs.
	CronAccountRemove(context.Context, *CronAccountRemoveRequest) (*CronAccountRemoveResponse, error)
	// CronStatus returns the last run of each of an account's jobs.
	CronStatus(context.Context, *CronStatusRequest) (*CronStatusResponse, error)
	// SiteLogTail returns the last lines of an account's access or error
	// log, oldest first; with contains, only lines holding that text.
	SiteLogTail(context.Context, *SiteLogTailRequest) (*SiteLogTailResponse, error)
	// SiteLogRead returns a part of an account's log and its size, for
	// downloading it part by part.
	SiteLogRead(context.Context, *SiteLogReadRequest) (*SiteLogReadResponse, error)
	mustEmbedUnimplementedAgentServiceServer()
}

